foreach ($entry in $urls.GetEnumerator()) {
  $name = $entry.Key
  $url = $entry.Value
  $out = "stitch-html\$name.html"
  try {
    Invoke-WebRequest -Uri $url -OutFile $out -UseBasicParsing
    "OK: $name ($((Get-Item $out).Length) bytes)"
  } catch {
    "FAIL: $name - $_"
  }
}
